package app.officinalibri;

import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.zip.*;

/** App-private copies only. Archives are streamed, never extracted onto user documents. */
public final class MobileStore {
    public static final long LIMIT=1024L*1024*1024, FILE_LIMIT=100L*1024*1024;
    public final File books, staging;
    public MobileStore(File root)throws Exception {books=new File(root,"books");staging=new File(root,"staging");Files.createDirectories(books.toPath());Files.createDirectories(staging.toPath());}
    public static boolean allowed(String name){return name.matches("(manifest\\.json|romanzo\\.json|percorso\\.json|assets/[a-f0-9]{64}\\.(png|jpg|pdf)|novel-fonts/[a-f0-9]{64}\\.(ttf|otf)|imports/([a-f0-9]{64}\\.docx|word-[a-f0-9]{64}\\.json)|snapshots/[a-zA-Z0-9-]+\\.json)");}
    private static String id(String value)throws IOException {if(!value.matches("[a-f0-9-]{36}"))throw new IOException("Progetto non riconosciuto");return value;}
    public File folder(String value){try{return new File(books,id(value));}catch(IOException e){throw new IllegalArgumentException(e);}}
    public static JSONObject json(File file)throws Exception {if(file.length()>32L*1024*1024)throw new IOException("Documento JSON oltre 32 MiB");return new JSONObject(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));}
    public static void atomic(File file,String value)throws Exception {Files.createDirectories(file.getParentFile().toPath());File tmp=new File(file.getPath()+"."+UUID.randomUUID()+".tmp");try{try(FileOutputStream out=new FileOutputStream(tmp)){out.write(value.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}try{Files.move(tmp.toPath(),file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(tmp.toPath());}}
    public static String hash(File file)throws Exception {MessageDigest h=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] buf=new byte[65536];for(int n;(n=in.read(buf))!=-1;)h.update(buf,0,n);}StringBuilder s=new StringBuilder();for(byte b:h.digest())s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
    public JSONObject read(String value)throws Exception {return readFolder(folder(value),value);}
    public JSONObject prepared(String value)throws Exception {File root=new File(staging,id(value));JSONObject state=readFolder(root,value);validateResources(root,state);return state;}
    private JSONObject readFolder(File root,String value)throws Exception {JSONObject p=json(new File(root,"manifest.json")),n=json(new File(root,"romanzo.json"));if(!p.getString("id").equals(n.getString("projectId")))throw new IOException("Progetto e romanzo diversi");JourneyStore.validate(root,p);JSONArray fonts=new JSONArray();File[] fontFiles=new File(root,"novel-fonts").listFiles();if(fontFiles!=null)for(File f:fontFiles)if(f.getName().matches("[a-f0-9]{64}\\.(ttf|otf)"))fonts.put(f.getName());return new JSONObject().put("id",value).put("project",p).put("novel",n).put("fontFiles",fonts);}
    public JSONArray list()throws Exception {
        JSONArray result=new JSONArray();File[] dirs=books.listFiles(File::isDirectory);if(dirs==null)return result;
        JSONObject bindings=new JSONObject();try{File state=new File(books.getParentFile(),"drive-state.json");if(state.isFile())bindings=json(state).getJSONObject("books");}catch(Exception ignored){}
        List<JSONObject> plain=new ArrayList<>();
        for(File dir:dirs)try{JSONObject state=read(dir.getName()),p=state.getJSONObject("project"),binding=bindings.optJSONObject(dir.getName());long changed=new File(dir,"romanzo.json").lastModified();
            if(binding!=null)try{changed=Math.max(changed,java.time.Instant.parse(binding.optString("lastSync")).toEpochMilli());}catch(Exception ignored){}
            JSONObject row=new JSONObject().put("id",dir.getName()).put("title",p.getString("title")+(binding==null?"":" · Drive")).put("synced",binding!=null).put("chapters",state.getJSONObject("novel").getJSONArray("sections").length()).put("changedAt",changed);
            plain.add(row);
        }catch(Exception ignored){}
        plain.sort((a,b)->Long.compare(b.optLong("changedAt"),a.optLong("changedAt")));for(JSONObject row:plain)result.put(row);return result;
    }
    public JSONObject create(JSONObject state)throws Exception {String value=UUID.randomUUID().toString();File root=folder(value);Files.createDirectory(root.toPath());JSONObject p=state.getJSONObject("project"),n=state.getJSONObject("novel");if(!"romanzo".equals(p.getString("kind"))||!p.getString("id").equals(n.getString("projectId")))throw new IOException("Progetto non valido");atomic(new File(root,"manifest.json"),p.toString());atomic(new File(root,"romanzo.json"),n.toString());return read(value);}
    public JSONObject save(String value,JSONObject next)throws Exception {return save(value,next,true);}
    public JSONObject save(String value,JSONObject next,boolean checkpoint)throws Exception {File root=folder(value),target=new File(root,"romanzo.json");JSONObject old=json(target);if(old.getInt("revision")!=next.getInt("revision")||!old.getString("projectId").equals(next.getString("projectId")))throw new IOException("Revisione cambiata: riapri il romanzo prima di salvare");File marker=new File(root,"checkpoint.time");long now=System.currentTimeMillis();if(checkpoint||!marker.exists()||now-marker.lastModified()>30000||now<marker.lastModified()){atomic(new File(root,"snapshots/romanzo-"+old.getInt("revision")+"-"+UUID.randomUUID()+".json"),old.toString());atomic(marker,String.valueOf(now));}next.put("revision",old.getInt("revision")+1);atomic(target,next.toString());return next;}
    public JSONArray history(String value)throws Exception {File dir=new File(folder(value),"snapshots");File[] files=dir.listFiles((d,n)->n.matches("romanzo-[0-9]+-[a-f0-9-]+\\.json"));JSONArray result=new JSONArray();if(files!=null){Arrays.sort(files,Comparator.comparingInt((File f)->Integer.parseInt(f.getName().split("-")[1])).reversed());for(File f:files)result.put(f.getName());}return result;}
    public JSONObject restore(String value,String name,int revision)throws Exception {if(!name.matches("romanzo-[0-9]+-[a-f0-9-]+\\.json"))throw new IOException("Versione non riconosciuta");JSONObject n=json(new File(folder(value),"snapshots/"+name));n.put("revision",revision);return save(value,n);}
    public JSONObject importArchive(InputStream input)throws Exception {
        String value=UUID.randomUUID().toString();File root=new File(staging,value);Files.createDirectory(root.toPath());Set<String> seen=new HashSet<>();long total=0;
        try {
        try(ZipInputStream zip=new ZipInputStream(new BufferedInputStream(input))){ZipEntry entry;byte[] buf=new byte[65536];while((entry=zip.getNextEntry())!=null){String name=entry.getName();if((!allowed(name)&&!name.equals("transfer.json"))||!seen.add(name)||seen.size()>10001)throw new IOException("Archivio non ammesso: percorso o duplicato");File target=new File(root,name);Files.createDirectories(target.getParentFile().toPath());long size=0;try(OutputStream out=new FileOutputStream(target)){for(int n;(n=zip.read(buf))!=-1;){size+=n;total+=n;if(size>FILE_LIMIT||total>LIMIT)throw new IOException("Archivio oltre i limiti: 100 MiB per file, 1 GiB complessivo");out.write(buf,0,n);}}zip.closeEntry();}}
        JSONObject report=json(new File(root,"transfer.json"));JSONArray records=report.getJSONArray("files");if(!"officina-transfer-1".equals(report.getString("format"))||records.length()!=seen.size()-1)throw new IOException("Inventario incompleto");Set<String> checked=new HashSet<>();for(int i=0;i<records.length();i++){JSONObject record=records.getJSONObject(i);String name=record.getString("path");if(!allowed(name)||!seen.contains(name)||!checked.add(name))throw new IOException("Inventario non valido");File file=new File(root,name);if(file.length()!=record.getLong("bytes")||!hash(file).equals(record.getString("sha256")))throw new IOException("File non integro: "+name);}
        JSONObject state=readFolder(root,value);validateResources(root,state);if(!report.getString("projectId").equals(state.getJSONObject("project").getString("id"))||report.getInt("novelRevision")!=state.getJSONObject("novel").getInt("revision"))throw new IOException("Revisione archivio incoerente");return state;
        }catch(Exception e){discard(value);throw e;}
    }
    private static Iterable<String> keys(JSONObject object){List<String> result=new ArrayList<>();Iterator<String> iterator=object.keys();while(iterator.hasNext())result.add(iterator.next());return result;}
    private static void validateResources(File root,JSONObject state)throws Exception {JourneyStore.validate(root,state.getJSONObject("project"));for(String kind:Arrays.asList("project","novel")){JSONObject object=state.getJSONObject(kind),assets=object.optJSONObject("assets");if(assets!=null)for(String name:keys(assets)){if(!allowed("assets/"+name))throw new IOException("Risorsa non ammessa");JSONObject meta=assets.getJSONObject(name);File f=new File(root,"assets/"+name);if(!f.isFile()||f.length()!=meta.getLong("bytes")||!hash(f).equals(meta.getString("sha256")))throw new IOException("Immagine mancante o non integra");}if(kind.equals("project")&&object.has("font")){String key=object.getJSONObject("font").getString("sha256");if(!key.matches("[a-f0-9]{64}"))throw new IOException("Font generale non valido");File regular=new File(root,"novel-fonts/"+key+".ttf");if(!regular.isFile())regular=new File(root,"novel-fonts/"+key+".otf");if(!regular.isFile()||!hash(regular).equals(key))throw new IOException("Font del progetto mancante: riesporta la copia dal PC");}JSONObject fonts=object.optJSONObject("fonts");if(fonts!=null)for(String key:keys(fonts)){JSONObject meta=fonts.getJSONObject(key);String name=meta.getString("file");if(!allowed("novel-fonts/"+name))throw new IOException("Font non ammesso");File f=new File(root,"novel-fonts/"+name);if(!f.isFile()||!hash(f).equals(meta.getJSONObject("ref").getString("sha256")))throw new IOException("Font mancante o non integro");}}}
    public void discard(String value)throws Exception {File root=new File(staging,id(value));if(!root.getCanonicalFile().getParentFile().equals(staging.getCanonicalFile()))throw new IOException("Cartella temporanea non ammessa");if(root.exists())try(java.util.stream.Stream<Path> paths=Files.walk(root.toPath())){for(Path file:paths.sorted(Comparator.reverseOrder()).collect(java.util.stream.Collectors.toList()))Files.delete(file);}}
    public JSONObject accept(String value)throws Exception {File from=new File(staging,id(value)),to=folder(value);if(to.exists())throw new IOException("Copia già presente");Files.move(from.toPath(),to.toPath());return read(value);}
    private static void collect(File root,String prefix,List<String> names)throws Exception {File[] children=new File(root,prefix).listFiles();if(children==null)return;for(File f:children){String name=prefix.isEmpty()?f.getName():prefix+"/"+f.getName();if(Files.isSymbolicLink(f.toPath()))throw new IOException("Link non ammesso");if(f.isDirectory()){if(Arrays.asList("assets","novel-fonts","imports","snapshots").contains(name))collect(root,name,names);}else if(allowed(name))names.add(name);}}
    public void exportArchive(String value,OutputStream output)throws Exception {File root=folder(value);JSONObject state=read(value);List<String> names=new ArrayList<>();collect(root,"",names);Collections.sort(names);JSONArray records=new JSONArray();long total=0;for(String name:names){File f=new File(root,name);total+=f.length();if(f.length()>FILE_LIMIT||total>LIMIT||names.size()>10000)throw new IOException("Copia oltre i limiti di trasferimento");records.put(new JSONObject().put("path",name).put("bytes",f.length()).put("sha256",hash(f)));}JSONObject report=new JSONObject().put("format","officina-transfer-1").put("projectId",state.getJSONObject("project").getString("id")).put("novelRevision",state.getJSONObject("novel").getInt("revision")).put("createdAt",java.time.Instant.now().toString()).put("files",records);try(ZipOutputStream zip=new ZipOutputStream(new BufferedOutputStream(output))){byte[] buf=new byte[65536];for(String name:names){zip.putNextEntry(new ZipEntry(name));try(InputStream in=new FileInputStream(new File(root,name))){for(int n;(n=in.read(buf))!=-1;)zip.write(buf,0,n);}zip.closeEntry();}zip.putNextEntry(new ZipEntry("transfer.json"));zip.write(report.toString().getBytes(StandardCharsets.UTF_8));zip.closeEntry();}}
}
